window.RP_SESSION={"id":"S-2712361652ab","messages":[{"id":"RP-II-0158918","time":"2026-08-21T20:34:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"아니... 흠. 그건 안 될 걸.\"","characters":[]},{"id":"RP-II-0158919","time":"2026-08-21T20:34:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"아니지. 우선 만까지는 끌어들여야 한다네.\"","characters":[]},{"id":"RP-II-0158920","time":"2026-08-21T20:34:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"해안가. 모래밭에 나뭇가지로 대략적인 지도를 그려놓고 혼자서 중얼중얼.","characters":[]},{"id":"RP-II-0158921","time":"2026-08-21T20:34:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"그의 곁에는 검 한자루 뿐입니다.","characters":[]},{"id":"RP-II-0158922","time":"2026-08-21T20:35:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"밧줄로 되려나? 쇠사슬이 준비될지는 모르겠군.\"","characters":[]},{"id":"RP-II-0158923","time":"2026-08-21T20:37:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"오. 그렇군. 10척이 전부 소리질러서 소통할리는 없으니.\"","characters":[]},{"id":"RP-II-0158924","time":"2026-08-21T20:38:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"음. 아니. 그 말은 방금 끝냈지 않은가.\"","characters":[]},{"id":"RP-II-0158925","time":"2026-08-21T20:39:00+09:00","room":"RP II","name":"하비에르","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"토르번 행님, 그러면 마법사 행님의 도움을 받죠?\"","characters":["P-dee7f622fa88"]},{"id":"RP-II-0158926","time":"2026-08-21T20:39:00+09:00","room":"RP II","name":"하비에르","profile":"델타인","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-dee7f622fa88"]},{"id":"RP-II-0158927","time":"2026-08-21T20:39:00+09:00","room":"RP II","name":"하비에르","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이 건의는 토르번에게 죽도록 두들겨 맞던 2인조 중 하나인 하비에르의 것!","characters":["P-dee7f622fa88"]},{"id":"RP-II-0158928","time":"2026-08-21T20:39:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"음? 어떤 도움 말인가. 자세히 얘기해보게.\"","characters":[]},{"id":"RP-II-0158929","time":"2026-08-21T20:40:00+09:00","room":"RP II","name":"하비에르","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"우리 앞바다가 행님 생각보다 얕습니다.\"","characters":["P-dee7f622fa88"]},{"id":"RP-II-0158930","time":"2026-08-21T20:40:00+09:00","room":"RP II","name":"하비에르","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"썰물 때는요.\"","characters":["P-dee7f622fa88"]},{"id":"RP-II-0158931","time":"2026-08-21T20:40:00+09:00","room":"RP II","name":"하비에르","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"썰물 때 그 시키들이 오면 큰 배로는 해변까지 못 들어올 겁니다.\"","characters":["P-dee7f622fa88"]},{"id":"RP-II-0158932","time":"2026-08-21T20:41:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"음. 결국 접근하려면 작은 배로 옮겨타서 와야겠더라고.\"","characters":[]},{"id":"RP-II-0158933","time":"2026-08-21T20:41:00+09:00","room":"RP II","name":"하비에르","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"예, 그르니까 마법사 행님이 마법을 쏘면 못 피하고 다 맞지 않겠습니까?\"","characters":["P-dee7f622fa88"]},{"id":"RP-II-0158934","time":"2026-08-21T20:42:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"맞는 말일세. 다만, 놈들이 접근을 미루고 포로 먼저 무력화를 시도한다면 큰일일세.\"","characters":[]},{"id":"RP-II-0158935","time":"2026-08-21T20:43:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"그래서, 끌어들일 미끼 작전을 생각중이었다네.\"","characters":[]},{"id":"RP-II-0158936","time":"2026-08-21T20:43:00+09:00","room":"RP II","name":"하비에르","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"미끼요?\"","characters":["P-dee7f622fa88"]},{"id":"RP-II-0158937","time":"2026-08-21T20:43:00+09:00","room":"RP II","name":"하비에르","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"음.\"","characters":["P-dee7f622fa88"]},{"id":"RP-II-0158938","time":"2026-08-21T20:43:00+09:00","room":"RP II","name":"하비에르","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"흠.\"","characters":["P-dee7f622fa88"]},{"id":"RP-II-0158939","time":"2026-08-21T20:43:00+09:00","room":"RP II","name":"하비에르","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"으흠.\"","characters":["P-dee7f622fa88"]},{"id":"RP-II-0158940","time":"2026-08-21T20:43:00+09:00","room":"RP II","name":"하비에르","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"저랑 라울 행님이 가서 해적 놈들 약을 막 올릴까요?\"","characters":["P-dee7f622fa88"]},{"id":"RP-II-0158941","time":"2026-08-21T20:43:00+09:00","room":"RP II","name":"하비에르","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"라울 행님은 제가 약 올리면 무조건 쫓아오시던데.\"","characters":["P-dee7f622fa88"]},{"id":"RP-II-0158942","time":"2026-08-21T20:43:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"ㅋㅋㅋㅋㅋ그거 잘 하긴 하더군.\"","characters":[]},{"id":"RP-II-0158943","time":"2026-08-21T20:44:00+09:00","room":"RP II","name":"하비에르","profile":"델타인","identity":"reviewed","type":"dialogue","body":"하비에르에게서 익숙한 델타인의 향기가 조금씩….","characters":["P-dee7f622fa88"]},{"id":"RP-II-0158944","time":"2026-08-21T20:45:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"이모티콘","characters":[]},{"id":"RP-II-0158945","time":"2026-08-21T20:45:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"아 맞다. 큰 배에 쓰는 홋줄이나 사슬 두껍고 긴~ 거 있는가?\"","characters":[]},{"id":"RP-II-0158946","time":"2026-08-21T20:46:00+09:00","room":"RP II","name":"하비에르","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아이, 당연히 있지요.\"","characters":["P-dee7f622fa88"]},{"id":"RP-II-0158947","time":"2026-08-21T20:48:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"좋아. 정비해서 챙겨두고 나한테 보고하게. 어디든 요긴하게 쓰겠어.\"","characters":[]},{"id":"RP-II-0158948","time":"2026-08-21T21:23:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"계속해서 끄적끄적...\n\n\"포의 수는 너무 적어. 몇몇 개는 마을 안에 산개시켜 숨겨두는 게?\"\n\n\"놈들은... 뭍으로 들어오지 못한다. 놈들도 알테니 접근하지 않을 걸세. 작은 배로 옮겨타서 올 때 마법사와 대포로 괴롭혀주고....\"","characters":[]},{"id":"RP-II-0158949","time":"2026-08-21T21:24:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"만 안으로 강제로 끌어올 수 있다면 기동력을 빼앗을 수 있을텐데... 기함을 노려서 고래가 밀거나, 물어 당기는 방식으로?\"\n\n\"기함을 구분할 수 있을지 모르겠군.\"","characters":[]},{"id":"RP-II-0158950","time":"2026-08-21T21:24:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"어쨌거나 홋줄을 해안가에 숨겨두면 유연하게 사용할 수 있을 거야.\"","characters":[]},{"id":"RP-II-0158951","time":"2026-08-21T21:24:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"고래를 직접 크라켄과 싸우게 하고 싶지는 않은데. 도망치며 유인할 수 있을지... 불가하다면 최대한 해적선 놈들의 배와 가까이에서 싸우게 해야해. 포가 흔들리겠지?\"","characters":[]},{"id":"RP-II-0158952","time":"2026-08-21T21:35:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"격멸시킬 필요는 없네. 목표는 결국 포기하게 만드는 것이니까.\"","characters":[]},{"id":"RP-II-0158953","time":"2026-08-21T21:36:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"기함과 3척 정도를 무력화시키는 방법을 1안.\"\n\"5척 정도를 무력화시키는 방법을 2안으로 다시 짜보지.\"","characters":[]},{"id":"RP-II-0158954","time":"2026-08-21T21:37:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"똑똑","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158955","time":"2026-08-21T21:38:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"저 해변에 아무렇게나 걸터 앉아있어요.","characters":[]},{"id":"RP-II-0158956","time":"2026-08-21T21:38:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"저런","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158957","time":"2026-08-21T21:38:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"아무튼 존이 다가왔습니다","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158958","time":"2026-08-21T21:38:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"중얼중얼...","characters":[]},{"id":"RP-II-0158959","time":"2026-08-21T21:38:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"음? 존 형씨.\"","characters":[]},{"id":"RP-II-0158960","time":"2026-08-21T21:38:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"흐암... 토르번씨... 지금 마법진 도안을 몇개 준비해봤는데 검토 좀 부탁드려도 될까요...\"","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158961","time":"2026-08-21T21:38:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"눈 밑이 쾡~","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158962","time":"2026-08-21T21:39:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"오. 어디 보여주게나.\"","characters":[]},{"id":"RP-II-0158963","time":"2026-08-21T21:39:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"일단 크게 3종류인데요. 방어용 하나, 교란용 하나, 공격용 하나에요\"","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158964","time":"2026-08-21T21:40:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"존이 대략 10가지 정도의 도안들을 보여줍니더","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158965","time":"2026-08-21T21:40:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"음. 계속 설명해주게.\"","characters":[]},{"id":"RP-II-0158966","time":"2026-08-21T21:40:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"자 우선 방어용인데... 어떤식으로 방어하는게 가장 효율적일지 고민해봤거든요\"","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158967","time":"2026-08-21T21:41:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"존이 도안 중 3개를 보여줍니다","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158968","time":"2026-08-21T21:43:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"하나는 안개인데... 근처가 바다라서 발동이 쉬울거에요. 이거는 신기루 환영, 적들이 함포를 가지고있다면 조준을 흩어놓는 용이고, 마지막 하나는 적들이 배에서 내릴 때를 노리는 환각마법이에요\"","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158969","time":"2026-08-21T21:44:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"음... 안개는 제하지. 오히려 지대가 낮은 우리 측에서 대응이 어려울 수도 있겠어.\"","characters":[]},{"id":"RP-II-0158970","time":"2026-08-21T21:44:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"좋아요. 그럼 이거는 빼고...\"","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158971","time":"2026-08-21T21:44:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"놈들은 마을로 초점을 잡아두고 막 갈겨도 되겠지만 우리는 포가 적으니 바다는 잘 보여야 할 걸세.\"","characters":[]},{"id":"RP-II-0158972","time":"2026-08-21T21:45:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"그럼 신기루도 크게 의미가 없을지도 모르겠네요...\"","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158973","time":"2026-08-21T21:45:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"공격용을 늘리는 게 나을지도 모르겠네.\"","characters":[]},{"id":"RP-II-0158974","time":"2026-08-21T21:46:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"흠, 그럼 공격용도 보여드릴게요\"","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158975","time":"2026-08-21T21:46:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"어디보자...\"","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158976","time":"2026-08-21T21:47:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"일단 이건 낙뢰마법인데, 아마 한번 밖에 못쓸거 같아요.\"","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158977","time":"2026-08-21T21:48:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"그리고 이거는 환각인데... 적들을 기절시키는 방향으로 준비했구요\"","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158978","time":"2026-08-21T21:48:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"그리고 이거 하나는 혹시라도 크라켄이 나타나면 써볼까 싶어서 준비한건데, 통할 지는 모르겠네요\"","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158979","time":"2026-08-21T21:49:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"크라켄은 최대한 고래와 싸우게 하고 싶지 않군.\"","characters":[]},{"id":"RP-II-0158980","time":"2026-08-21T21:49:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"통한다면 좋으련만.\"","characters":[]},{"id":"RP-II-0158981","time":"2026-08-21T21:49:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"\"놈들이 분명 배는 멀리 대어두고 작은 보트로 갈아타서 접근할 걸세. 그 때 낙뢰를 바다에 떨어뜨리면 효과가 좋겠지.\"","characters":[]},{"id":"RP-II-0158982","time":"2026-08-21T21:50:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"적어도 적의 배 하나는 무력화시킬 수 있을지도 몰라요\"","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158983","time":"2026-08-21T21:50:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"그래서 1회용이지만...","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158984","time":"2026-08-21T21:51:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"자, 그럼 마지막으로 교란용 마법들인데\"","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158985","time":"2026-08-21T21:52:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"저번에 라리에나씨에게 물어보니 아직 심해교단의 배를 쓸 수 있더라구요\"","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158986","time":"2026-08-21T21:52:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"그래서 광역 기절마법을 배에 설치해서, 수면 아래로 이동한 뒤 적진 가운데에서 터트리면 좋지 않나 생각해봤어요\"","characters":["P-ed77659dbe40"]},{"id":"RP-II-0158987","time":"2026-08-21T21:53:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"물론 배가 위험해지니 다소 도박이지만요\"","characters":["P-ed77659dbe40"]}]};
